import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useAuth } from "../context/AuthContext";

const GRADS = ["rt1","rt2","rt3","rt4","rt5","rt6"];

const statusBadge = (status) => {
  if (status === "Upcoming")  return { bg: "var(--teal-lt)",  color: "var(--teal)",  label: "Upcoming"  };
  if (status === "Completed") return { bg: "#E8F4FF",          color: "#1A6FAB",      label: "Completed" };
  if (status === "Cancelled") return { bg: "var(--coral-lt)", color: "var(--coral)", label: "Cancelled" };
  return { bg: "var(--tag)", color: "var(--muted)", label: status };
};

export default function DashboardPage() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const [bookings, setBookings] = useState([]);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(true);
  const [cancelMsg, setCancelMsg] = useState("");

  useEffect(() => {
    if (!user) { navigate("/auth"); return; }
    axios.get("/api/bookings/my")
      .then(r => setBookings(r.data.bookings))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [user]);

  const handleCancel = async (id) => {
    if (!window.confirm("Cancel this booking?")) return;
    try {
      await axios.patch(`/api/bookings/${id}/cancel`);
      setBookings(prev => prev.map(b => b._id === id ? { ...b, status: "Cancelled" } : b));
      setCancelMsg("Booking cancelled successfully.");
    } catch (err) {
      setCancelMsg(err.response?.data?.message || "Could not cancel.");
    }
  };

  const totalSpent  = bookings.filter(b => b.status !== "Cancelled").reduce((s, b) => s + b.totalPrice, 0);
  const upcoming    = bookings.filter(b => b.status === "Upcoming");
  const completed   = bookings.filter(b => b.status === "Completed");

  const initials = user ? `${user.first_name?.[0] || ""}${user.last_name?.[0] || ""}` : "?";

  const NAV_ITEMS = [
    { key: "overview",  icon: "🏠", label: "Overview"    },
    { key: "bookings",  icon: "📅", label: "My Bookings" },
    { key: "reviews",   icon: "⭐", label: "My Reviews"  },
    { key: "payments",  icon: "💳", label: "Payments"    },
    { key: "id",        icon: "🪪", label: "My ID & Docs"},
    { key: "settings",  icon: "⚙️", label: "Settings"   },
  ];

  return (
    <div style={{ display: "grid", gridTemplateColumns: "230px 1fr", minHeight: "calc(100vh - var(--nav-h))" }}>

      {/* ── Sidebar ── */}
      <aside style={{ background: "white", borderRight: "1px solid var(--border)", padding: "24px 14px" }}>
        <div style={{ textAlign: "center", paddingBottom: 20, marginBottom: 20, borderBottom: "1px solid var(--border)" }}>
          <div style={{ width: 58, height: 58, borderRadius: "50%", background: "var(--gold-lt)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 19, fontWeight: 600, color: "var(--gold-dk)", margin: "0 auto 10px" }}>
            {initials}
          </div>
          <div style={{ fontWeight: 600, fontSize: 15 }}>{user?.first_name} {user?.last_name}</div>
          <div style={{ fontSize: 11, color: "var(--muted)" }}>{user?.email}</div>
        </div>

        <ul style={{ listStyle: "none", padding: 0 }}>
          {NAV_ITEMS.map(({ key, icon, label }) => (
            <li key={key} style={{ marginBottom: 2 }}>
              <button onClick={() => setActiveTab(key)} style={{
                width: "100%", display: "flex", alignItems: "center", gap: 10,
                padding: "10px 12px", borderRadius: "var(--r-sm)", textDecoration: "none",
                fontSize: 14, fontWeight: 500, cursor: "pointer", border: "none",
                background: activeTab === key ? "var(--gold-lt)" : "transparent",
                color: activeTab === key ? "var(--gold-dk)" : "var(--muted)",
                transition: "all .15s", textAlign: "left",
              }}>
                <span style={{ fontSize: 15, width: 20, textAlign: "center" }}>{icon}</span>
                {label}
              </button>
            </li>
          ))}
          <li style={{ marginTop: 16 }}>
            <button onClick={() => { logout(); navigate("/"); }} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 10,
              padding: "10px 12px", borderRadius: "var(--r-sm)", fontSize: 14, fontWeight: 500,
              cursor: "pointer", border: "none", background: "transparent", color: "var(--coral)", textAlign: "left",
            }}>
              <span style={{ fontSize: 15, width: 20, textAlign: "center" }}>🚪</span>Sign Out
            </button>
          </li>
        </ul>
      </aside>

      {/* ── Main Content ── */}
      <div style={{ background: "var(--cream)", padding: 32 }}>

        {cancelMsg && (
          <div style={{ background: "var(--teal-lt)", border: "1px solid var(--teal)", borderRadius: "var(--r-sm)", padding: "10px 14px", marginBottom: 16, fontSize: 13, color: "var(--teal)" }}>
            {cancelMsg}
          </div>
        )}

        {/* ══ OVERVIEW TAB ══ */}
        {activeTab === "overview" && (
          <>
            <div style={{ marginBottom: 28 }}>
              <h2 style={{ fontFamily: "'DM Serif Display',serif", fontSize: 26, marginBottom: 4 }}>
                Welcome back, {user?.first_name} 👋
              </h2>
              <p style={{ fontSize: 14, color: "var(--muted)" }}>Your account summary and recent activity</p>
            </div>

            {/* Stats */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 14, marginBottom: 28 }}>
              {[
                { num: bookings.length, lbl: "Total Bookings",   ch: `↑ ${upcoming.length} upcoming`,   up: true },
                { num: upcoming.length, lbl: "Upcoming Stays",   ch: "Active reservations",              up: true },
                { num: `$${totalSpent}`,lbl: "Total Spent",      ch: `${completed.length} completed`,    up: true },
                { num: completed.length,lbl: "Completed Stays",  ch: "Ready to review",                  up: true },
              ].map(({ num, lbl, ch, up }) => (
                <div key={lbl} style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 18 }}>
                  <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 28, marginBottom: 3 }}>{num}</div>
                  <div style={{ fontSize: 12, color: "var(--muted)", fontWeight: 500 }}>{lbl}</div>
                  <div style={{ fontSize: 12, marginTop: 7, color: up ? "var(--teal)" : "var(--coral)" }}>{up ? "↑" : "↓"} {ch}</div>
                </div>
              ))}
            </div>

            {/* Verified Badge */}
            <div style={{ background: "var(--teal-lt)", border: "1.5px solid var(--teal)", borderRadius: "var(--r-lg)", padding: "16px 20px", marginBottom: 20, display: "flex", alignItems: "center", gap: 14 }}>
              <span style={{ fontSize: 24 }}>🪪</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14, color: "var(--teal)" }}>Identity Verified</div>
                <div style={{ fontSize: 13, color: "var(--teal)" }}>Your national ID has been verified. You can book any room instantly.</div>
              </div>
              <span style={{ background: "var(--teal-lt)", color: "var(--teal)", fontSize: 11, fontWeight: 600, padding: "3px 9px", borderRadius: 999, border: "1px solid var(--teal)" }}>✓ Verified</span>
            </div>

            {/* Upcoming Stay highlight */}
            {upcoming.length > 0 && (
              <div style={{ background: "var(--gold-lt)", border: "1.5px solid var(--gold)", borderRadius: "var(--r-lg)", padding: "16px 20px", marginBottom: 20, display: "flex", alignItems: "center", gap: 16 }}>
                <div className={GRADS[0]} style={{ width: 64, height: 52, borderRadius: 8, flexShrink: 0 }} />
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", color: "var(--gold-dk)", marginBottom: 2 }}>Upcoming Stay</div>
                  <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 2 }}>{upcoming[0].roomId?.title || upcoming[0].roomId?.description?.substring(0,40) || upcoming[0].roomId?.type}</div>
                  <div style={{ fontSize: 13, color: "var(--gold-dk)" }}>
                    📅 {new Date(upcoming[0].startDate).toLocaleDateString()} – {new Date(upcoming[0].endDate).toLocaleDateString()} · ${upcoming[0].totalPrice} total
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button className="btn btn-out" style={{ padding: "8px 14px", fontSize: 12 }} onClick={() => navigate(`/rooms/${upcoming[0].roomId?._id}`)}>Details</button>
                  <button className="btn btn-dark" style={{ padding: "8px 14px", fontSize: 12 }} onClick={() => handleCancel(upcoming[0]._id)}>Cancel</button>
                </div>
              </div>
            )}

            {/* Recent Bookings Table */}
            <BookingTable bookings={bookings.slice(0, 5)} onCancel={handleCancel} navigate={navigate} />
          </>
        )}

        {/* ══ BOOKINGS TAB ══ */}
        {activeTab === "bookings" && (
          <>
            <div style={{ marginBottom: 28 }}>
              <h2 style={{ fontFamily: "'DM Serif Display',serif", fontSize: 26, marginBottom: 4 }}>My Bookings</h2>
              <p style={{ fontSize: 14, color: "var(--muted)" }}>All your reservations in one place</p>
            </div>
            {loading ? (
              <p style={{ color: "var(--muted)" }}>Loading…</p>
            ) : bookings.length === 0 ? (
              <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>
                <div style={{ fontSize: 48, marginBottom: 16 }}>📅</div>
                <p>You haven't made any bookings yet.</p>
                <button className="btn btn-gold" style={{ marginTop: 20 }} onClick={() => navigate("/explore")}>Explore Rooms</button>
              </div>
            ) : (
              <BookingTable bookings={bookings} onCancel={handleCancel} navigate={navigate} />
            )}
          </>
        )}

        {/* ══ OTHER TABS (placeholder) ══ */}
        {["reviews","payments","id","settings"].includes(activeTab) && (
          <div style={{ textAlign: "center", padding: "80px 0", color: "var(--muted)" }}>
            <div style={{ fontSize: 48, marginBottom: 16 }}>
              {{ reviews: "⭐", payments: "💳", id: "🪪", settings: "⚙️" }[activeTab]}
            </div>
            <h3 style={{ fontFamily: "'DM Serif Display',serif", fontSize: 22, marginBottom: 8, color: "var(--charcoal)" }}>
              {{ reviews: "My Reviews", payments: "Payment History", id: "ID & Documents", settings: "Account Settings" }[activeTab]}
            </h3>
            <p>This section is coming soon.</p>
          </div>
        )}
      </div>
    </div>
  );
}

/* ── Booking Table sub-component ── */
function BookingTable({ bookings, onCancel, navigate }) {
  return (
    <div style={{ background: "white", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "hidden" }}>
      <div style={{ padding: "16px 18px", borderBottom: "1px solid var(--border)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h3 style={{ fontSize: 15, fontWeight: 600 }}>Booking History</h3>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              {["Room","Dates","Total","Status","Actions"].map(h => (
                <th key={h} style={{ textAlign: "left", padding: "11px 14px", fontSize: 10, fontWeight: 700, letterSpacing: ".9px", textTransform: "uppercase", color: "var(--muted)", borderBottom: "1px solid var(--border)" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {bookings.map((b, i) => {
              const { bg, color, label } = statusBadge(b.status);
              return (
                <tr key={b._id} style={{ cursor: "pointer" }}
                  onMouseEnter={e => [...e.currentTarget.querySelectorAll("td")].forEach(td => td.style.background = "var(--cream)")}
                  onMouseLeave={e => [...e.currentTarget.querySelectorAll("td")].forEach(td => td.style.background = "white")}
                >
                  <td style={{ padding: "13px 14px", fontSize: 13, borderBottom: "1px solid var(--border)", verticalAlign: "middle" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <div className={GRADS[i % GRADS.length]} style={{ width: 42, height: 34, borderRadius: 6, flexShrink: 0 }} />
                      <div>
                        <div style={{ fontWeight: 500, fontSize: 13 }}>{b.roomId?.title || b.roomId?.description?.substring(0,30) || b.roomId?.type || "Room"}</div>
                        <div style={{ fontSize: 11, color: "var(--muted)" }}>{b.roomId?.location}, {b.roomId?.city}</div>
                      </div>
                    </div>
                  </td>
                  <td style={{ padding: "13px 14px", fontSize: 13, borderBottom: "1px solid var(--border)", color: "var(--muted)", verticalAlign: "middle" }}>
                    {new Date(b.startDate).toLocaleDateString()} – {new Date(b.endDate).toLocaleDateString()}
                  </td>
                  <td style={{ padding: "13px 14px", fontSize: 13, borderBottom: "1px solid var(--border)", fontWeight: 500, verticalAlign: "middle" }}>
                    ${b.totalPrice}
                  </td>
                  <td style={{ padding: "13px 14px", fontSize: 13, borderBottom: "1px solid var(--border)", verticalAlign: "middle" }}>
                    <span style={{ background: bg, color, fontSize: 11, fontWeight: 600, padding: "3px 9px", borderRadius: 999 }}>{label}</span>
                  </td>
                  <td style={{ padding: "13px 14px", fontSize: 13, borderBottom: "1px solid var(--border)", verticalAlign: "middle" }}>
                    <div style={{ display: "flex", gap: 6 }}>
                      <button className="btn btn-out" style={{ padding: "4px 10px", fontSize: 12 }}
                        onClick={() => navigate(`/rooms/${b.roomId?._id}`)}>View</button>
                      {b.status === "Upcoming" && (
                        <button className="btn btn-out" style={{ padding: "4px 10px", fontSize: 12, color: "var(--coral)", borderColor: "var(--coral)" }}
                          onClick={() => onCancel(b._id)}>Cancel</button>
                      )}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
